import postgres from 'postgres';
const sql = postgres(process.env.DATABASE_URL, {ssl:'require'});
console.log(await sql`SELECT current_status, sub_status, (sub_cancelled_at IS NOT NULL) canc, (sub_expiry_date < current_date) exp, count(*)::int n FROM onboarding_cases GROUP BY 1,2,3,4 ORDER BY 1,5 DESC`);
await sql.end();
