import json,collections,datetime as dt,statistics as st,sys
S=sys.argv[1]; d=json.load(open(f'{S}/all.json'))
IST=dt.timedelta(hours=5,minutes=30)
def T(s): return dt.datetime.fromisoformat(s.replace('Z','+00:00'))
W0=dt.datetime(2026,9,10,tzinfo=dt.timezone.utc)-IST; W1=dt.datetime(2026,11,2,tzinfo=dt.timezone.utc)-IST  # IST 10 Sep 00:00 .. 2 Nov 00:00
names=sorted(d['ag'],key=len,reverse=True)
def target(rem):
    rem=rem or ''; i=rem.lower().find('assigned to ')
    if i<0: return None
    rest=rem[i+12:]
    return next((n for n in names if rest.startswith(n)),None)
WORK={'new_event','historical_import','revival_call'}
LIVE={'OB_ADS_LIVE'}; LOST={'OB_NOT_INTERESTED','OB_REFUND_REQUESTED','OB_NOT_INTERESTED_REFUND','OB_REFUND_PROCESSED'}
REOPEN={'SYSTEM_AD_FAILED_AFTER_LIVE','SYSTEM_ADS_LIVE_NOT_VERIFIED','SYSTEM_LOST_REMOVED','SYSTEM_CALLBACK_REOPENED','SYSTEM_REOPENED','SYSTEM_EXTERNAL_ADS_LIVE_REVERSED'}
def status_change(e):
    c=e['l0_code']; l=(e['l0l'] or '').strip()
    if c=='SYSTEM_EXTERNAL_ADS_LIVE': return 'ext'
    if c in REOPEN: return 'open'
    if e['src'] not in WORK and c!='OB_REFUND_PROCESSED': return None
    if c in LIVE or (c is None and l=='Ads Live'): return 'live'
    if c in LOST: return 'lost'
    if c in ('OB_IN_PROCESS','OB_NOT_CONNECTED') or (c is None and l in ('Call Back','In Process','Not Connected','Call Cut in Between')): return 'open'
    return None
cases={c['cid']:c for c in d['cs']}
ev=collections.defaultdict(list)
for e in d['ev']: e['T']=T(e['t']); ev[e['cid']].append(e)
LAG=[0]
R=collections.defaultdict(lambda:collections.Counter()); check=collections.Counter()
for cid,c in cases.items():
    es=sorted(ev.get(cid,[]),key=lambda e:(e['T'],e['n']))
    for i,e in enumerate(es):
        if e['l0_code']=='OB_ADS_LIVE' and e['agent']:
            for f in es[i+1:]:
                if f['T']-e['T']>dt.timedelta(hours=24): break
                if f['l0_code'] in ('SYSTEM_ASSIGNED','SYSTEM_REASSIGNED') and target(f['remark'])==e['agent']:
                    f['T']=e['T']-dt.timedelta(seconds=1); LAG[0]+=1; break
    es.sort(key=lambda e:(e['T'],e['n']))
    # ownership spells
    first_asg=next((e for e in es if e['l0_code'] in ('SYSTEM_ASSIGNED','SYSTEM_REASSIGNED','SELLER_HANDOFF') and target(e['remark'])),None)
    if first_asg is None: owner=c['owner']
    else:
        pre=[e for e in es if e['T']<first_asg['T'] and e['src'] in WORK and e['agent']]
        owner=pre[0]['agent'] if pre else target(first_asg['remark'])
    # replay
    status='open'; seg_start=min(e['T'] for e in es) if es else T(c['created_at'])
    spells=[]; cur={'who':owner,'start':seg_start,'events':[],'status0':status}
    for e in es:
        if e['l0_code'] in ('SYSTEM_ASSIGNED','SYSTEM_REASSIGNED','SELLER_HANDOFF'):
            to=target(e['remark'])
            if to and to!=cur['who']:
                cur['end']=e['T']; spells.append(cur); cur={'who':to,'start':e['T'],'events':[],'status0':status}
            continue
        s=status_change(e)
        if s: status=s; cur['events'].append((e['T'],s,e['agent']))
    cur['end']=None; spells.append(cur)
    fin={'ext':'ads_live','live':'ads_live','lost':'lost','open':'open'}[status]
    check[(fin==c['current_status'] or (c['current_status']=='closed'))]+=1
    for sp in spells:
        a=max(sp['start'],W0); b=min(sp['end'] or W1,W1)
        if a>=b or not sp['who']: continue
        st0=sp['status0']
        for t,s,_ in sp['events']:
            if t<a: st0=s
        inseg=[s for t,s,_ in sp['events'] if a<=t<b]
        lastlive=[g for t,s,g in sp['events'] if a<=t<b and s=='live']
        if st0 in ('live','ext','lost') and not inseg: continue  # already done, not in play
        end=inseg[-1] if inseg else st0
        if end=='live': k='live'
        elif end=='ext': k='ext'
        elif end=='lost': k='lost'
        elif sp['end'] and sp['end']<W1: k='moved'
        else: k='open'
        R[sp['who']][k]+=1
print('replay matches current status:',check,'lag fixes:',LAG[0])
days={}
for x in json.load(open(f'{S}/daily.json')):
    if x['d']<'2026-11-02': days[x['name']]=days.get(x['name'],0)+1
out=[]
for n,c in R.items():
    if n not in days: continue
    owned=sum(c.values()); base=c['live']+c['lost']+c['open']
    out.append(dict(name=n,days=days[n],owned=owned,live=c['live'],lost=c['lost'],open=c['open'],moved=c['moved'],ext=c['ext'],
        eff=c['live']/base if base else 0, prod=c['live']/days[n]))
json.dump(out,open(f'{S}/own_out.json','w'))
for o in sorted(out,key=lambda o:-o['eff']): print(f"{o['name']:<18}{o['days']:>4}{o['owned']:>5}{o['live']:>5}{o['lost']:>5}{o['open']:>5}{o['moved']:>6}{o['ext']:>4}{o['eff']:>7.0%}{o['prod']:>6.2f}")
print('not workers:',[ (n,sum(c.values())) for n,c in R.items() if n not in days])
